import{calculateChaosAction,calculateEyeOrder,calculateFinalSafeZone,calculateKefkaAction,finalCards,initialState,phaseLabel}from'./domain/mechanics.js';import{createCombatEventSource,MockCombatEventSource}from'./services/combatEventSource.js';
const STORAGE_KEY='umad-p4-helper-state',phases=['exdeath','chaos','kefka','final'];let state=load(),open={exdeath:true,chaos:false,kefka:false,final:false},confirmReset=false;function load(){try{return structuredClone({...initialState,...JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}')})}catch{return structuredClone(initialState)}}function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}function setState(next){state=typeof next==='function'?next(state):{...state,...next};save();autoOpen();render()}function autoOpen(){if(!state.settings.autoOpenCurrentPhase)return;open=Object.fromEntries(phases.map(p=>[p,state.settings.autoClosePreviousPhase?p===state.phase:open[p]||p===state.phase]))}function icon(n){return`<span class="icon icon-${n}" aria-hidden="true"></span>`}function mark(v){return v==='true'?'O':v==='false'?'-':'?'}function truth(path,value,allowFalse=false){const opts=allowFalse?['true','unknown','false']:['true','unknown'];return`<div class="truth-buttons">${opts.map(v=>`<button data-set="${path}" data-value="${v}" class="${value===v?'selected':''}">${mark(v)}</button>`).join('')}</div>`}function row(iconName,label,path,value,result='',allowFalse=false){return`<div class="mechanic-row"><span class="mechanic-name">${icon(iconName)}${label}</span>${truth(path,value,allowFalse)}${result?`<strong class="result-pill">${result}</strong>`:''}</div>`}function accordion(title,phase,body){return`<section class="card ${state.phase===phase?'current':''}"><button class="card-head" data-toggle="${phase}"><span>${open[phase]?'▼':'▲'} ${title}</span><b>${state.phase===phase?'현재':''}</b></button>${open[phase]?`<div class="card-body">${body}</div>`:''}</section>`}function setPath(path,value){const [group,key]=path.split('.');setState(s=>({...s,[group]:{...s[group],[key]:value}}))}function reset(){if(!confirmReset){confirmReset=true;setTimeout(()=>{confirmReset=false;render()},2500);render();return}state=structuredClone(initialState);open={exdeath:true,chaos:false,kefka:false,final:false};confirmReset=false;save();render()}function summary(active,title,items){return`<span class="summary ${active?'active':''}"><b>${title}</b>${items.map(i=>`<small>${i}</small>`).join('')}</span>`}function render(){const finalId=calculateFinalSafeZone(state),finalLabel=finalCards.find(c=>c.id===finalId)?.label,eye=calculateEyeOrder(state.exdeath);if(state.collapsed){app.innerHTML=`<div class="shell compact"><button class="compact-main" data-collapse="false"><b>요성난무 4P</b>${finalLabel?`<span class="active">FINAL</span><strong>${finalLabel}</strong>`:`${summary(state.phase==='exdeath','EXD',[`물 ${mark(state.exdeath.water)}`,`번개 ${mark(state.exdeath.thunder)}`,`폭탄 ${mark(state.exdeath.bomb)}`,eye==='look-then-away'?'마안 1보기→2안보기':'마안 1안보기→2보기'])}${summary(state.phase==='chaos','CHAOS',[`불 ${mark(state.chaos.fire)}`,`물 ${mark(state.chaos.water)}`])}${summary(state.phase==='kefka','KEFKA',[`선더가 ${mark(state.kefka.thunder)}`,`블리자가 ${mark(state.kefka.blizzard)}`])}`} ${icon('expand')}</button></div>`;bind();return}app.innerHTML=`<main class="shell"><header><div><h1>요성난무 4페이즈 도우미</h1><p>작은 창용 접이식 수동 입력 헬퍼</p></div><button class="reset" data-reset>${icon('reset')}${confirmReset?'한 번 더':'초기화'}</button><button data-collapse="true">${icon('collapse')}접기</button></header><nav>${phases.map(p=>`<button data-phase="${p}" class="${state.phase===p?'active':''}">${phaseLabel(p)}</button>`).join('')}</nav>${accordion('엑스데스','exdeath',`<p class="hint">물/번개/폭탄은 디버프 시간순으로 입력, 마안은 현재 상태에서 자동 표시됩니다.</p>${row('water','물','exdeath.water',state.exdeath.water)}${row('lightning','번개','exdeath.thunder',state.exdeath.thunder)}${row('bomb','폭탄','exdeath.bomb',state.exdeath.bomb,'',true)}<div class="eye">${icon('eye')}<b>마안</b><span>${eye==='look-then-away'?'1 보기 → 2 안보기':'1 안보기 → 2 보기'}</span></div>`)}${accordion('카오스','chaos',`${row('fire','불','chaos.fire',state.chaos.fire,calculateChaosAction('fire',state.chaos.fire))}${row('water','물','chaos.water',state.chaos.water,calculateChaosAction('water',state.chaos.water))}`)}${accordion('케프카','kefka',`<p class="hint">1마안 / 2산쉐 때 저장합니다.</p>${row('lightning','선더가','kefka.thunder',state.kefka.thunder,calculateKefkaAction(state.kefka.thunder))}${row('ice','블리자가','kefka.blizzard',state.kefka.blizzard,calculateKefkaAction(state.kefka.blizzard))}`)}${accordion('최종 안전지대','final',`<div class="final-grid">${finalCards.map(c=>`<div class="final-card ${finalId===c.id?'winner':''} ${finalId&&finalId!==c.id?'dim':''}"><small>${c.pattern.map(mark).join(' / ')}</small><b>${c.label}</b></div>`).join('')}</div>${!finalId?'<p class="pending">결과 미확정: 케프카 선더가/블리자가 입력이 필요합니다.</p>':''}`)}<section class="settings">${[['alwaysOnTop','항상 위에 표시'],['resetOnCombatEnd','전투 종료 시 자동 초기화'],['autoOpenCurrentPhase','현재 페이즈 자동 펼치기'],['autoClosePreviousPhase','이전 페이즈 자동 접기']].map(([k,l])=>`<label><input data-setting="${k}" type="checkbox" ${state.settings[k]?'checked':''}>${l}</label>`).join('')}</section><details class="mock"><summary>${icon('connection')}Mock 테스트</summary><div>${phases.map(p=>`<button data-mock="${p}">${phaseLabel(p)}</button>`).join('')}<button data-combat-end>전투 종료</button></div></details></main>`;bind()}function bind(){document.querySelectorAll('[data-set]').forEach(b=>b.onclick=()=>setPath(b.dataset.set,b.dataset.value));document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{open[b.dataset.toggle]=!open[b.dataset.toggle];render()});document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>setState({phase:b.dataset.phase}));document.querySelectorAll('[data-collapse]').forEach(b=>b.onclick=()=>setState({collapsed:b.dataset.collapse==='true'}));document.querySelectorAll('[data-setting]').forEach(i=>i.onchange=()=>setState(s=>({...s,settings:{...s.settings,[i.dataset.setting]:i.checked}})));document.querySelector('[data-reset]')?.addEventListener('click',reset);document.querySelectorAll('[data-mock]').forEach(b=>b.onclick=()=>MockCombatEventSource.emit({type:'PhaseChanged',phase:b.dataset.mock}));document.querySelector('[data-combat-end]')?.addEventListener('click',()=>MockCombatEventSource.emit({type:'CombatEnded'}))}createCombatEventSource().connect(ev=>{if(ev.type==='CombatEnded'&&state.settings.resetOnCombatEnd){state=structuredClone(initialState);save();render()}if(ev.type==='PhaseChanged')setState({phase:ev.phase})});window.addEventListener('keydown',e=>{if(e.ctrlKey&&e.key.toLowerCase()==='m')setState({collapsed:!state.collapsed});if(e.ctrlKey&&e.key.toLowerCase()==='r')reset()});render();
